<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];$other=(int)($_GET['user']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rid=(int)$_POST['receiver_id'];$text=trim($_POST['message_text']??'');if($text){$s=$pdo->prepare("INSERT INTO Messages(sender_id,receiver_id,message_text) VALUES(?,?,?)");$s->execute([$uid,$rid,$text]);}redirect('messages.php?user='.$rid);}
if($other){$pdo->prepare("UPDATE Messages SET is_read=1 WHERE receiver_id=? AND sender_id=?")->execute([$uid,$other]);$s=$pdo->prepare("SELECT m.*,u.first_name,u.last_name FROM Messages m JOIN Users u ON u.user_id=m.sender_id WHERE (m.sender_id=? AND m.receiver_id=?) OR (m.sender_id=? AND m.receiver_id=?) ORDER BY m.sent_at");$s->execute([$uid,$other,$other,$uid]);$conversation=$s->fetchAll();$q=$pdo->prepare("SELECT user_id,first_name,last_name FROM Users WHERE user_id=?");$q->execute([$other]);$person=$q->fetch();}
$people=$pdo->prepare("SELECT DISTINCT u.user_id,u.first_name,u.last_name FROM Users u JOIN Messages m ON u.user_id=CASE WHEN m.sender_id=? THEN m.receiver_id ELSE m.sender_id END WHERE (m.sender_id=? OR m.receiver_id=?)");$people->execute([$uid,$uid,$uid]);$people=$people->fetchAll();$title='Messages';include 'includes/header.php';
?>
<div class="messages-layout"><aside class="card"><h3>Conversations</h3><?php foreach($people as $p):?><a class="conversation-link <?=$other==$p['user_id']?'active':''?>" href="messages.php?user=<?=$p['user_id']?>"><span class="avatar small"><?=e(initials($p['first_name'],$p['last_name']))?></span><?=e($p['first_name'].' '.$p['last_name'])?></a><?php endforeach;?></aside><section class="card chat"><?php if($other):?><div class="chat-head"><h2><?=e($person['first_name'].' '.$person['last_name'])?></h2></div><div class="chat-body"><?php foreach($conversation as $m):?><div class="bubble <?=$m['sender_id']==$uid?'mine':''?>"><?=e($m['message_text'])?><small><?=e($m['sent_at'])?></small></div><?php endforeach;?></div><form method="post" class="chat-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="receiver_id" value="<?=$other?>"><input name="message_text" placeholder="Write a message..." required><button class="btn">Send</button></form><?php else:?><div class="empty">Choose a conversation.</div><?php endif;?></section></div>
<?php include 'includes/footer.php'; ?>
